(function () {
    var root = document.querySelector('[data-video-cate-sections]');
    if (!root) return;
    var pi = document.getElementById('page_info');
    var ds = pi ? pi.dataset : {};
    var PUBLIC_API_URL = (ds.publicApiUrl || '').trim().replace(/\/+$/, '');
    var CDN_URL = (ds.cdnUrl || '').trim().replace(/\/+$/, '');
    if (!PUBLIC_API_URL) return;
    var PER_PAGE = 4;

    function escapeHtml(v) {
        return String(v === null || v === undefined ? '' : v)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }
    function absPath(s) {
        s = String(s || '').trim();
        if (!s) return '';
        if (/^https?:\/\//i.test(s)) return s;
        return s.charAt(0) === '/' ? s : '/' + s;
    }
    function coverUrl(article) {
        var path = '';
        if (article && article.avatar1 && typeof article.avatar1.file_url === 'string') path = article.avatar1.file_url.trim();
        else if (article && article.avatar2 && typeof article.avatar2.file_url === 'string') path = article.avatar2.file_url.trim();
        else if (article && typeof article.avatar1_url === 'string') path = article.avatar1_url.trim();
        if (!path) return '';
        if (/^(https?:)?\/\//i.test(path)) return path;
        if (!CDN_URL) return path;
        return CDN_URL + '/' + path.replace(/^\/+/, '');
    }
    function hrefOf(article) {
        var s = (article && typeof article.slug === 'string' && article.slug.trim()) ? article.slug.trim()
            : (article && typeof article.article_url === 'string' ? article.article_url.trim() : '');
        return s ? absPath(s) : '#';
    }
    function titleOf(article) {
        if (article && typeof article.title === 'string' && article.title.trim()) return article.title.trim();
        if (article && typeof article.brief_title === 'string' && article.brief_title.trim()) return article.brief_title.trim();
        return 'Đang cập nhật';
    }
    function pad(n) { return n < 10 ? '0' + n : '' + n; }
    function formatDate(article) {
        var raw = article && (article.publish_date || article.article_publish_date || article.created_at || article.updated_at);
        if (!raw) return '';
        var d = new Date(raw);
        if (isNaN(d.getTime())) return '';
        return pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear();
    }
    function renderCard(article) {
        var href = escapeHtml(hrefOf(article));
        var title = escapeHtml(titleOf(article));
        var cover = escapeHtml(coverUrl(article));
        var date = escapeHtml(formatDate(article));
        return '<article class="t:flex t:flex-col t:gap-y-2.5">'
            + '<figure class="img-block t:relative t:overflow-hidden t:rounded-md" style="aspect-ratio: 16 / 9;">'
            + '<a href="' + href + '"><img src="' + cover + '" alt="' + title + '" loading="lazy" /></a>'
            + '<span aria-hidden="true" class="t:pointer-events-none t:absolute t:inset-0 t:flex t:items-center t:justify-center">'
            + '<span class="t:inline-flex t:size-10 t:items-center t:justify-center t:rounded-full t:bg-white/90 t:text-[#212636] t:backdrop-blur-sm">'
            + '<i class="ph--play-fill t:text-[16px]"></i>'
            + '</span></span>'
            + '</figure>'
            + '<h3 class="title l3 noto t:font-semibold"><a href="' + href + '">' + title + '</a></h3>'
            + (date ? '<time class="article-date"><i class="material-symbols--calendar-month-rounded"></i> ' + date + '</time>' : '')
            + '</article>';
    }
    function fetchPage(cateId, offset) {
        var url = PUBLIC_API_URL + '/v1/category/' + encodeURIComponent(cateId) + '/articles?limit=' + PER_PAGE + '&offset=' + offset;
        return fetch(url, { headers: { Accept: 'application/json' } })
            .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
            .then(function (p) {
                if (!p || p.success === false) throw new Error('Invalid payload');
                var data = Array.isArray(p.data) ? p.data : [];
                var meta = (p.meta && typeof p.meta === 'object') ? p.meta : {};
                var total = null;
                if (meta.total != null && !isNaN(parseInt(meta.total, 10))) total = parseInt(meta.total, 10);
                else if (p.total != null && !isNaN(parseInt(p.total, 10))) total = parseInt(p.total, 10);
                return { data: data, total: total };
            });
    }
    function setupSection(section) {
        var grid = section.querySelector('[data-cate-grid]');
        var moreBtn = section.querySelector('[data-cate-more]');
        var moreWrap = section.querySelector('[data-cate-more-wrap]') || (moreBtn ? moreBtn.parentNode : null);
        var cateId = section.getAttribute('data-cate-id');
        if (!grid || !cateId) return;
        var state = { offset: 0, loading: false, done: false, total: null };
        function hideMore() { if (moreWrap) moreWrap.style.display = 'none'; }
        function load(initial) {
            if (state.loading || state.done) return;
            state.loading = true;
            if (moreBtn) { moreBtn.disabled = true; moreBtn.setAttribute('aria-busy', 'true'); }
            fetchPage(cateId, state.offset).then(function (res) {
                var articles = res.data;
                if (typeof res.total === 'number') state.total = res.total;
                if (initial && (!articles || !articles.length)) { section.style.display = 'none'; state.done = true; return; }
                if (articles && articles.length) {
                    grid.insertAdjacentHTML('beforeend', articles.map(renderCard).join(''));
                    state.offset += articles.length;
                }
                var noMore = (!articles || articles.length < PER_PAGE) || (state.total !== null && state.offset >= state.total);
                if (noMore) { state.done = true; hideMore(); }
            }).catch(function (e) {
                if (initial) section.style.display = 'none';
                state.done = true; hideMore();
                if (window.console) console.error('[video-detail-cate]', e);
            }).then(function () {
                state.loading = false;
                if (moreBtn) { moreBtn.disabled = false; moreBtn.removeAttribute('aria-busy'); }
            });
        }
        if (moreBtn) moreBtn.addEventListener('click', function () { load(false); });
        load(true);
    }
    Array.prototype.forEach.call(root.querySelectorAll('[data-cate-section]'), setupSection);
})();
